import"./chunk-VC46IEJQ.js";var n={en:"Not described in the novels",zh:"\u5C0F\u8BF4\u4E2D\u672A\u4F5C\u63CF\u8FF0"},e=(o,r,a,t={})=>({id:o,name:{en:r,zh:a},...t}),s={group:"stormlands",houses:[{id:"baratheon",names:{en:"House Baratheon",zh:"\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF"},region:"stormlands",seat:"storms-end",tier:"great",liege:null,sigil:{en:"A crowned black stag on a gold field",zh:"\u91D1\u5E95\u4E0A\u4E00\u5934\u6234\u51A0\u7684\u9ED1\u8272\u96C4\u9E7F"},colors:["#e2b33c","#141414"],words:{en:"Ours Is the Fury",zh:"\u6012\u706B\u71CE\u539F"},summary:{en:"Founded by Orys Baratheon, Aegon the Conqueror's companion, who won Storm's End by slaying the last Storm King and marrying his daughter. Lords Paramount of the Stormlands for three centuries, the Baratheons took the Iron Throne when Robert overthrew Aerys II in 283 AC, with his brothers Stannis at Dragonstone and Renly at Storm's End.",zh:"\u7531\u5F81\u670D\u8005\u4F0A\u803F\u7684\u4F19\u4F34\u5965\u91CC\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u521B\u7ACB\uFF1A\u4ED6\u65A9\u6740\u672B\u4EE3\u98CE\u66B4\u4E4B\u738B\u3001\u8FCE\u5A36\u5176\u5973\uFF0C\u4ECE\u800C\u5F97\u5230\u98CE\u606F\u5821\u3002\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF\u4F5C\u4E3A\u98CE\u66B4\u5730\u6700\u9AD8\u7EDF\u6CBB\u8005\u5386\u65F6\u4E09\u767E\u5E74\uFF1B283\u5E74\u52B3\u52C3\u63A8\u7FFB\u4F0A\u91CC\u65AF\u4E8C\u4E16\uFF0C\u767B\u4E0A\u94C1\u738B\u5EA7\uFF0C\u5176\u5F1F\u53F2\u5766\u5C3C\u65AF\u5750\u9547\u9F99\u77F3\u5C9B\uFF0C\u84DD\u793C\u9886\u6709\u98CE\u606F\u5821\u3002"},refs:["agot","acok","asos","twoiaf"],members:[e("orys-baratheon","Orys Baratheon","\u5965\u91CC\u65AF\xB7\u62DC\u62C9\u5E2D\u6069",{spouses:["argella-durrandon"],note:{en:"Founder of the house; Aegon I's closest friend and first Hand, rumoured a bastard half-brother of the king.",zh:"\u5BB6\u65CF\u521B\u59CB\u4EBA\uFF1B\u4F0A\u803F\u4E00\u4E16\u7684\u631A\u53CB\u4E0E\u9996\u4EFB\u56FD\u738B\u4E4B\u624B\uFF0C\u4F20\u95FB\u662F\u56FD\u738B\u540C\u7236\u5F02\u6BCD\u7684\u79C1\u751F\u5144\u5F1F\u3002"}}),e("ormund-baratheon","Ormund Baratheon","\u5965\u8499\u5FB7\xB7\u62DC\u62C9\u5E2D\u6069",{spouses:["rhaelle-targaryen"],note:{en:"Lord of Storm's End; married Rhaelle Targaryen, daughter of Aegon V \u2014 the source of the Baratheons' Targaryen blood.",zh:"\u98CE\u606F\u5821\u516C\u7235\uFF0C\u5A36\u4F0A\u803F\u4E94\u4E16\u4E4B\u5973\u857E\u62C9\xB7\u5766\u683C\u5229\u5B89\u4E3A\u59BB\uFF0C\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF\u7684\u5766\u683C\u5229\u5B89\u8840\u7EDF\u5373\u7531\u6B64\u800C\u6765\u3002"}}),e("steffon-baratheon","Steffon Baratheon","\u53F2\u8482\u82AC\xB7\u62DC\u62C9\u5E2D\u6069",{father:"ormund-baratheon",mother:"rhaelle-targaryen",spouses:["cassana-estermont"],note:{en:"Lord of Storm's End; drowned with his wife when their ship broke up in Shipbreaker Bay.",zh:"\u98CE\u606F\u5821\u516C\u7235\uFF1B\u4E0E\u59BB\u5B50\u4E00\u540C\u5728\u7834\u8239\u6E7E\u56E0\u5EA7\u8239\u89E3\u4F53\u800C\u6EBA\u4EA1\u3002"}}),e("robert-baratheon","Robert Baratheon","\u52B3\u52C3\xB7\u62DC\u62C9\u5E2D\u6069",{father:"steffon-baratheon",mother:"cassana-estermont",spouses:["cersei-lannister"],note:{en:"Robert I, first of his name; won the throne in the rebellion of 282\u2013283 AC.",zh:"\u52B3\u52C3\u4E00\u4E16\uFF1B\u5728282\u81F3283\u5E74\u7684\u53DB\u4E71\u4E2D\u593A\u5F97\u738B\u4F4D\u3002"},fate:{en:"Mortally wounded by a boar while hunting in the kingswood (A Game of Thrones).",zh:"\u5728\u5FA1\u6797\u72E9\u730E\u65F6\u88AB\u91CE\u732A\u91CD\u4F24\u81F4\u6B7B\uFF08\u300A\u6743\u529B\u7684\u6E38\u620F\u300B\uFF09\u3002"}}),e("stannis-baratheon","Stannis Baratheon","\u53F2\u5766\u5C3C\u65AF\xB7\u62DC\u62C9\u5E2D\u6069",{father:"steffon-baratheon",mother:"cassana-estermont",spouses:["selyse-florent"],note:{en:"Lord of Dragonstone and master of ships; held Storm's End through a year-long siege.",zh:"\u9F99\u77F3\u5C9B\u516C\u7235\u3001\u8230\u961F\u53F8\u4EE4\uFF1B\u66FE\u575A\u5B88\u98CE\u606F\u5821\u957F\u8FBE\u4E00\u5E74\u3002"}}),e("renly-baratheon","Renly Baratheon","\u84DD\u793C\xB7\u62DC\u62C9\u5E2D\u6069",{father:"steffon-baratheon",mother:"cassana-estermont",spouses:["margaery-tyrell"],note:{en:"Lord of Storm's End and master of laws; youngest of the three brothers.",zh:"\u98CE\u606F\u5821\u516C\u7235\u3001\u6CD5\u52A1\u5927\u81E3\uFF1B\u4E09\u5144\u5F1F\u4E2D\u6700\u5C0F\u7684\u4E00\u4E2A\u3002"},fate:{en:"Crowns himself and marries Margaery Tyrell, then is killed in his tent by a shadow before Storm's End (A Clash of Kings).",zh:"\u81EA\u7ACB\u4E3A\u738B\u5E76\u8FCE\u5A36\u739B\u683C\u4E3D\xB7\u63D0\u5229\u5C14\uFF0C\u968F\u540E\u5728\u98CE\u606F\u5821\u57CE\u4E0B\u7684\u8425\u5E10\u4E2D\u88AB\u4E00\u9053\u5F71\u5B50\u523A\u6740\uFF08\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\uFF09\u3002"}}),e("shireen-baratheon","Shireen Baratheon","\u5E0C\u7433\xB7\u62DC\u62C9\u5E2D\u6069",{father:"stannis-baratheon",mother:"selyse-florent",note:{en:"Only child of Stannis; her face is scarred by greyscale survived in infancy.",zh:"\u53F2\u5766\u5C3C\u65AF\u7684\u72EC\u5973\uFF1B\u5E7C\u5E74\u60A3\u7070\u9CDE\u75C5\u5E78\u5B58\uFF0C\u8138\u4E0A\u7559\u4E0B\u75A4\u75D5\u3002"}}),e("joffrey-baratheon","Joffrey Baratheon","\u4E54\u4F5B\u91CC\xB7\u62DC\u62C9\u5E2D\u6069",{father:"robert-baratheon",mother:"cersei-lannister",note:{en:"Robert's eldest son and heir by Queen Cersei; king after him.",zh:"\u52B3\u52C3\u4E0E\u745F\u66E6\u738B\u540E\u7684\u957F\u5B50\u4E0E\u7EE7\u627F\u4EBA\uFF0C\u52B3\u52C3\u6B7B\u540E\u7EE7\u4F4D\u4E3A\u738B\u3002"},fate:{en:"Actually fathered by Jaime Lannister. Dies poisoned at his own wedding feast (A Storm of Swords).",zh:"\u5176\u751F\u7236\u5B9E\u4E3A\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u3002\u5728\u81EA\u5DF1\u7684\u5A5A\u5BB4\u4E0A\u4E2D\u6BD2\u8EAB\u4EA1\uFF08\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\uFF09\u3002"}}),e("myrcella-baratheon","Myrcella Baratheon","\u5F25\u8D5B\u83C8\xB7\u62DC\u62C9\u5E2D\u6069",{father:"robert-baratheon",mother:"cersei-lannister",note:{en:"Robert's daughter by Cersei; sent to Dorne as the betrothed of Prince Trystane Martell.",zh:"\u52B3\u52C3\u4E0E\u745F\u66E6\u4E4B\u5973\uFF1B\u4F5C\u4E3A\u5D14\u65AF\u5766\xB7\u9A6C\u6CF0\u5C14\u738B\u5B50\u7684\u672A\u5A5A\u59BB\u88AB\u9001\u5F80\u591A\u6069\u3002"},fate:{en:"Actually fathered by Jaime Lannister. Wounded in the face during a failed plot to crown her in Dorne (A Feast for Crows).",zh:"\u5176\u751F\u7236\u5B9E\u4E3A\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u3002\u5728\u591A\u6069\u4E00\u573A\u62E5\u7ACB\u5979\u4E3A\u5973\u738B\u7684\u5931\u8D25\u9634\u8C0B\u4E2D\u9762\u90E8\u53D7\u4F24\uFF08\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\uFF09\u3002"}}),e("tommen-baratheon","Tommen Baratheon","\u6258\u66FC\xB7\u62DC\u62C9\u5E2D\u6069",{father:"robert-baratheon",mother:"cersei-lannister",note:{en:"Robert's younger son by Cersei.",zh:"\u52B3\u52C3\u4E0E\u745F\u66E6\u7684\u5E7C\u5B50\u3002"},fate:{en:"Actually fathered by Jaime Lannister. Becomes king after Joffrey's death (A Storm of Swords).",zh:"\u5176\u751F\u7236\u5B9E\u4E3A\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u3002\u4E54\u4F5B\u91CC\u6B7B\u540E\u7EE7\u4F4D\u4E3A\u738B\uFF08\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\uFF09\u3002"}}),e("gendry","Gendry","\u8A79\u5FB7\u5229",{father:"robert-baratheon",note:{en:"A smith's apprentice in King's Landing, one of Robert's unacknowledged bastards; his mother was a tavern woman.",zh:"\u541B\u4E34\u4E00\u540D\u94C1\u5320\u5B66\u5F92\uFF0C\u52B3\u52C3\u672A\u88AB\u627F\u8BA4\u7684\u79C1\u751F\u5B50\u4E4B\u4E00\uFF1B\u6BCD\u4EB2\u662F\u4E00\u540D\u9152\u9986\u5973\u5B50\u3002"}}),e("edric-storm","Edric Storm","\u827E\u5FB7\u745E\u514B\xB7\u98CE\u66B4",{father:"robert-baratheon",note:{en:"Robert's only acknowledged bastard, born of Delena Florent and raised at Storm's End.",zh:"\u52B3\u52C3\u552F\u4E00\u88AB\u627F\u8BA4\u7684\u79C1\u751F\u5B50\uFF0C\u6BCD\u4EB2\u662F\u6234\u83B2\u5A1C\xB7\u4F5B\u7F57\u4F26\uFF0C\u5728\u98CE\u606F\u5821\u957F\u5927\u3002"}}),e("mya-stone","Mya Stone","\u7C73\u4E9A\xB7\u77F3\u4E1C",{father:"robert-baratheon",note:{en:"Robert's bastard daughter from his youth in the Vale; a mule-guide on the Eyrie's mountain road.",zh:"\u52B3\u52C3\u5C11\u5E74\u65F6\u671F\u5728\u8C37\u5730\u6240\u751F\u7684\u79C1\u751F\u5973\uFF1B\u5728\u9E70\u5DE2\u57CE\u5C71\u9053\u4E0A\u8D76\u9AA1\u5F15\u8DEF\u3002"}})]},{id:"durrandon",names:{en:"House Durrandon",zh:"\u675C\u5170\u767B\u5BB6\u65CF"},region:"stormlands",seat:"storms-end",tier:"extinct",liege:null,sigil:{en:"A crowned black stag on a gold field (later taken up by the Baratheons)",zh:"\u91D1\u5E95\u4E0A\u4E00\u5934\u6234\u51A0\u7684\u9ED1\u8272\u96C4\u9E7F\uFF08\u540E\u4E3A\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF\u6CBF\u7528\uFF09"},colors:["#e2b33c","#141414"],words:{en:"Ours Is the Fury",zh:"\u6012\u706B\u71CE\u539F"},summary:{en:"The Storm Kings, who ruled the stormlands from Storm's End for thousands of years, descended in legend from Durran Godsgrief. The line ended in the male branch with Argilac the Arrogant, slain by Orys Baratheon during Aegon's Conquest.",zh:"\u98CE\u66B4\u4E4B\u738B\uFF0C\u6570\u5343\u5E74\u95F4\u4ECE\u98CE\u606F\u5821\u7EDF\u6CBB\u98CE\u66B4\u5730\uFF0C\u4F20\u8BF4\u4E3A\u201C\u795E\u6012\u201D\u675C\u5170\u7684\u540E\u88D4\u3002\u5176\u7537\u7CFB\u8840\u8109\u7EC8\u7ED3\u4E8E\u201C\u50B2\u6162\u7684\u201D\u963F\u57FA\u62C9\u514B\u2014\u2014\u4ED6\u5728\u4F0A\u803F\u5F81\u670D\u6218\u4E89\u4E2D\u88AB\u5965\u91CC\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u6240\u6740\u3002"},refs:["agot","twoiaf"],members:[e("durran-durrandon","Durran Godsgrief","\u201C\u795E\u6012\u201D\u675C\u5170",{note:{en:"Legendary first Storm King, who wed a daughter of the sea god and goddess of the wind and built Storm's End.",zh:"\u4F20\u8BF4\u4E2D\u7684\u9996\u4F4D\u98CE\u66B4\u4E4B\u738B\uFF0C\u5A36\u6D77\u795E\u4E0E\u98CE\u4E4B\u5973\u795E\u7684\u5973\u513F\u4E3A\u59BB\uFF0C\u5EFA\u9020\u4E86\u98CE\u606F\u5821\u3002"}}),e("argilac-durrandon","Argilac the Arrogant","\u201C\u50B2\u6162\u7684\u201D\u963F\u57FA\u62C9\u514B",{note:{en:"Last Storm King; refused Aegon's terms and was slain at the Last Storm.",zh:"\u672B\u4EE3\u98CE\u66B4\u4E4B\u738B\uFF1B\u62D2\u7EDD\u4F0A\u803F\u7684\u6761\u4EF6\uFF0C\u5728\u201C\u6700\u540E\u7684\u98CE\u66B4\u201D\u4E4B\u6218\u4E2D\u88AB\u6740\u3002"}}),e("argella-durrandon","Argella Durrandon","\u963F\u6377\u62C9\xB7\u675C\u5170\u767B",{father:"argilac-durrandon",spouses:["orys-baratheon"],note:{en:"Argilac's daughter; married to Orys Baratheon after the conquest.",zh:"\u963F\u57FA\u62C9\u514B\u4E4B\u5973\uFF1B\u5F81\u670D\u6218\u4E89\u540E\u5AC1\u7ED9\u5965\u91CC\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u3002"}})]},{id:"estermont",names:{en:"House Estermont",zh:"\u4F0A\u65AF\u8499\u5BB6\u65CF"},region:"stormlands",seat:"greenstone",tier:"major",liege:"baratheon",sigil:{en:"A green sea turtle on purple",zh:"\u7D2B\u5E95\u4E0A\u4E00\u53EA\u7EFF\u8272\u6D77\u9F9F"},colors:["#5b3b7a","#3f8a4a"],summary:{en:"Lords of the island of Estermont, ruling from Greenstone. Lady Cassana Estermont married Steffon Baratheon and bore Robert, Stannis and Renly, so the Estermonts stand close in blood to the Baratheon kings.",zh:"\u4F0A\u65AF\u8499\u5C9B\u7684\u9886\u4E3B\uFF0C\u4EE5\u7EFF\u77F3\u5821\u4E3A\u5C45\u57CE\u3002\u5361\u73CA\u5A1C\xB7\u4F0A\u65AF\u8499\u592B\u4EBA\u5AC1\u7ED9\u53F2\u8482\u82AC\xB7\u62DC\u62C9\u5E2D\u6069\uFF0C\u751F\u4E0B\u52B3\u52C3\u3001\u53F2\u5766\u5C3C\u65AF\u548C\u84DD\u793C\uFF0C\u56E0\u6B64\u4F0A\u65AF\u8499\u5BB6\u65CF\u4E0E\u62DC\u62C9\u5E2D\u6069\u8BF8\u738B\u8840\u7F18\u6781\u8FD1\u3002"},refs:["acok","affc","twoiaf"],members:[e("cassana-estermont","Cassana Estermont","\u5361\u73CA\u5A1C\xB7\u4F0A\u65AF\u8499",{spouses:["steffon-baratheon"],note:{en:"Wife of Lord Steffon and mother of Robert, Stannis and Renly; drowned with him in Shipbreaker Bay.",zh:"\u53F2\u8482\u82AC\u516C\u7235\u4E4B\u59BB\uFF0C\u52B3\u52C3\u3001\u53F2\u5766\u5C3C\u65AF\u4E0E\u84DD\u793C\u4E4B\u6BCD\uFF1B\u4E0E\u4E08\u592B\u4E00\u540C\u6EBA\u4EA1\u4E8E\u7834\u8239\u6E7E\u3002"}}),e("eldon-estermont","Eldon Estermont","\u827E\u5C14\u767B\xB7\u4F0A\u65AF\u8499",{note:{en:"Lord of Greenstone; Cassana's brother, uncle of King Robert.",zh:"\u7EFF\u77F3\u5821\u4F2F\u7235\uFF1B\u5361\u73CA\u5A1C\u7684\u5144\u5F1F\uFF0C\u52B3\u52C3\u56FD\u738B\u7684\u8205\u7236\u3002"}}),e("aemon-estermont","Aemon Estermont","\u4F0A\u8499\xB7\u4F0A\u65AF\u8499",{father:"eldon-estermont",note:{en:"Lord Eldon's son and heir, a knight.",zh:"\u827E\u5C14\u767B\u4F2F\u7235\u4E4B\u5B50\u4E0E\u7EE7\u627F\u4EBA\uFF0C\u4E00\u540D\u9A91\u58EB\u3002"}}),e("alyn-estermont","Alyn Estermont","\u827E\u6797\xB7\u4F0A\u65AF\u8499",{father:"aemon-estermont",note:{en:"Ser Aemon's son, a young knight.",zh:"\u4F0A\u8499\u7235\u58EB\u4E4B\u5B50\uFF0C\u4E00\u540D\u5E74\u8F7B\u9A91\u58EB\u3002"}})]},{id:"tarth",names:{en:"House Tarth",zh:"\u5854\u65AF\u5BB6\u65CF"},region:"stormlands",seat:"evenfall-hall",tier:"major",liege:"baratheon",sigil:{en:"Quartered rose and azure, with golden suns and silver crescent moons",zh:"\u73AB\u7470\u7EA2\u4E0E\u5929\u84DD\u56DB\u5206\uFF0C\u9970\u4EE5\u91D1\u8272\u592A\u9633\u4E0E\u94F6\u8272\u65B0\u6708"},colors:["#d98aa0","#2f63b0"],summary:{en:"Lords of Tarth, the Sapphire Isle, ruling from Evenfall Hall; the lord of the house is styled the Evenstar. In the novels Lord Selwyn's only surviving child is Brienne, a towering woman who chose the sword over marriage.",zh:"\u84DD\u5B9D\u77F3\u5C9B\u5854\u65AF\u5C9B\u7684\u9886\u4E3B\uFF0C\u4EE5\u66AE\u4E34\u5385\u4E3A\u5C45\u57CE\uFF0C\u5BB6\u4E3B\u88AB\u5C0A\u79F0\u4E3A\u201C\u66AE\u661F\u201D\u3002\u5C0F\u8BF4\u4E2D\u8D5B\u5C14\u6E29\u4F2F\u7235\u552F\u4E00\u5728\u4E16\u7684\u5B69\u5B50\u662F\u5E03\u857E\u59AE\u2014\u2014\u4E00\u4F4D\u8EAB\u6750\u9AD8\u5927\u3001\u820D\u5A5A\u5AC1\u800C\u62E9\u5200\u5251\u7684\u5973\u5B50\u3002"},refs:["acok","affc","twoiaf"],members:[e("selwyn-tarth","Selwyn Tarth","\u8D5B\u5C14\u6E29\xB7\u5854\u65AF",{note:{en:"Lord of Tarth, the Evenstar.",zh:"\u5854\u65AF\u4F2F\u7235\uFF0C\u201C\u66AE\u661F\u201D\u3002"}}),e("galladon-tarth","Galladon Tarth","\u845B\u62C9\u987F\xB7\u5854\u65AF",{father:"selwyn-tarth",note:{en:"Brienne's elder brother; drowned as a boy.",zh:"\u5E03\u857E\u59AE\u7684\u54E5\u54E5\uFF1B\u5C11\u5E74\u65F6\u6EBA\u6C34\u8EAB\u4EA1\u3002"}}),e("brienne-tarth","Brienne of Tarth","\u5854\u65AF\u7684\u5E03\u857E\u59AE",{father:"selwyn-tarth",note:{en:"Lord Selwyn's heir; served in Renly's Rainbow Guard, then swore herself to Catelyn Stark.",zh:"\u8D5B\u5C14\u6E29\u4F2F\u7235\u7684\u7EE7\u627F\u4EBA\uFF1B\u66FE\u662F\u84DD\u793C\u7684\u5F69\u8679\u62A4\u536B\uFF0C\u540E\u5BA3\u8A93\u6548\u5FE0\u51EF\u7279\u7433\xB7\u53F2\u5854\u514B\u3002"},fate:{en:"Captured by the outlaws of the brotherhood, she is forced to promise to bring Jaime Lannister to their leader (A Feast for Crows / A Dance with Dragons).",zh:"\u88AB\u5144\u5F1F\u4F1A\u7684\u4EA1\u547D\u4E4B\u5F92\u4FD8\u864F\uFF0C\u88AB\u8FEB\u627F\u8BFA\u628A\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u5E26\u5230\u4ED6\u4EEC\u7684\u9996\u9886\u9762\u524D\uFF08\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\uFF09\u3002"}}),e("arianne-tarth","Arianne Tarth","\u827E\u8389\u5B89\xB7\u5854\u65AF",{father:"selwyn-tarth",note:{en:"A younger sister of Brienne who died in infancy.",zh:"\u5E03\u857E\u59AE\u7684\u59B9\u59B9\uFF0C\u592D\u6298\u4E8E\u8941\u8913\u4E4B\u4E2D\u3002"}}),e("alysanne-tarth","Alysanne Tarth","\u963F\u83B1\u838E\u59AE\xB7\u5854\u65AF",{father:"selwyn-tarth",note:{en:"A younger sister of Brienne who died in infancy.",zh:"\u5E03\u857E\u59AE\u7684\u59B9\u59B9\uFF0C\u592D\u6298\u4E8E\u8941\u8913\u4E4B\u4E2D\u3002"}})]},{id:"connington",names:{en:"House Connington",zh:"\u514B\u6797\u987F\u5BB6\u65CF"},region:"stormlands",seat:"griffins-roost",tier:"major",liege:"baratheon",sigil:{en:"Two griffins combatant, counterchanged red and white",zh:"\u7EA2\u767D\u5BF9\u5206\u7684\u4E24\u5934\u76F8\u6597\u72EE\u9E6B\uFF0C\u8272\u5F69\u4E92\u6362"},colors:["#b0262c","#f2efe6"],summary:{en:"Once among the proudest houses of the stormlands, ruling from Griffin's Roost. Lord Jon Connington was Hand to Aerys II and was exiled after losing the Battle of the Bells; his lands were cut down and the castle passed to a cousin's line.",zh:"\u4E00\u5EA6\u662F\u98CE\u66B4\u5730\u6700\u9A84\u50B2\u7684\u5BB6\u65CF\u4E4B\u4E00\uFF0C\u4EE5\u72EE\u9E6B\u6816\u606F\u5730\u4E3A\u5C45\u57CE\u3002\u743C\u6069\xB7\u514B\u6797\u987F\u4F2F\u7235\u66FE\u4EFB\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u9996\u76F8\uFF0C\u5728\u949F\u697C\u4E4B\u5F79\u5931\u8D25\u540E\u906D\u5230\u6D41\u653E\uFF1B\u5BB6\u65CF\u9886\u5730\u88AB\u524A\u51CF\uFF0C\u57CE\u5821\u8F6C\u7531\u5176\u5802\u4EB2\u4E00\u652F\u6267\u638C\u3002"},refs:["asos","affc","adwd","twoiaf"],members:[e("jon-connington","Jon Connington","\u743C\u6069\xB7\u514B\u6797\u987F",{note:{en:"Lord of Griffin's Roost, friend of Prince Rhaegar and Hand of the King; exiled in 283 AC and said to have drunk himself to death.",zh:"\u72EE\u9E6B\u6816\u606F\u5730\u4F2F\u7235\uFF0C\u96F7\u52A0\u738B\u5B50\u7684\u631A\u53CB\u3001\u56FD\u738B\u4E4B\u624B\uFF1B283\u5E74\u906D\u6D41\u653E\uFF0C\u636E\u8BF4\u5DF2\u9157\u9152\u800C\u6B7B\u3002"},fate:{en:'Alive in exile as the sellsword "Griff", guardian of the boy presented as Aegon Targaryen; he returns to Westeros with the Golden Company and contracts greyscale (A Dance with Dragons).',zh:"\u5176\u5B9E\u4ECD\u5728\u4E16\uFF0C\u5316\u540D\u4F63\u5175\u201C\u683C\u91CC\u592B\u201D\uFF0C\u5B88\u62A4\u90A3\u4F4D\u81EA\u79F0\u4F0A\u803F\xB7\u5766\u683C\u5229\u5B89\u7684\u5C11\u5E74\uFF1B\u4ED6\u968F\u9EC4\u91D1\u56E2\u91CD\u8FD4\u7EF4\u65AF\u7279\u6D1B\uFF0C\u5E76\u67D3\u4E0A\u7070\u9CDE\u75C5\uFF08\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\uFF09\u3002"}}),e("ronnet-connington","Ronnet Connington","\u7F57\u5185\xB7\u514B\u6797\u987F",{note:{en:`"Red Ronnet", a knight of Griffin's Roost and cousin of Jon.`,zh:"\u201C\u7EA2\u53D1\u7F57\u5185\u201D\uFF0C\u72EE\u9E6B\u6816\u606F\u5730\u7684\u9A91\u58EB\uFF0C\u743C\u6069\u7684\u5802\u4EB2\u3002"}})]},{id:"dondarrion",names:{en:"House Dondarrion",zh:"\u5510\u5FB7\u5229\u6069\u5BB6\u65CF"},region:"stormlands",seat:"blackhaven",tier:"minor",liege:"baratheon",sigil:{en:"A forked purple lightning bolt on a black field strewn with stars",zh:"\u7F00\u6EE1\u661F\u8FB0\u7684\u9ED1\u5E95\u4E0A\u4E00\u9053\u7D2B\u8272\u53C9\u72B6\u95EA\u7535"},colors:["#151425","#8b4bb8"],summary:{en:"Marcher lords of Blackhaven in the Dornish Marches. Lord Beric Dondarrion, the house's young lord in the novels, leads a royal force into the riverlands and becomes the heart of an outlaw band that fights for the smallfolk.",zh:"\u591A\u6069\u8FB9\u7586\u5730\u9ED1\u6E2F\u57CE\u7684\u8FB9\u7586\u8BF8\u4FAF\u3002\u5C0F\u8BF4\u4E2D\u5BB6\u65CF\u7684\u5E74\u8F7B\u9886\u4E3B\u8D1D\u91CC\xB7\u5510\u5FB7\u5229\u6069\u7387\u9886\u738B\u5BB6\u961F\u4F0D\u8FDB\u5165\u6CB3\u95F4\u5730\uFF0C\u540E\u6765\u6210\u4E3A\u4E00\u652F\u4E3A\u5E73\u6C11\u800C\u6218\u7684\u4EA1\u547D\u4E4B\u5F92\u961F\u4F0D\u7684\u6838\u5FC3\u3002"},refs:["agot","asos","twoiaf"],members:[e("beric-dondarrion","Beric Dondarrion","\u8D1D\u91CC\xB7\u5510\u5FB7\u5229\u6069",{note:{en:'Lord of Blackhaven, the "Lightning Lord".',zh:"\u9ED1\u6E2F\u57CE\u4F2F\u7235\uFF0C\u201C\u95EA\u7535\u5927\u738B\u201D\u3002"},fate:{en:"Killed and brought back several times by the red priest Thoros of Myr; he finally gives his last life to raise Catelyn Stark (A Storm of Swords).",zh:"\u591A\u6B21\u6B7B\u53BB\u53C8\u88AB\u5BC6\u5C14\u7684\u7EA2\u888D\u50E7\u7D22\u7F57\u65AF\u590D\u6D3B\uFF1B\u6700\u7EC8\u732E\u51FA\u81EA\u5DF1\u6700\u540E\u7684\u751F\u547D\uFF0C\u590D\u6D3B\u4E86\u51EF\u7279\u7433\xB7\u53F2\u5854\u514B\uFF08\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\uFF09\u3002"}})]},{id:"caron",names:{en:"House Caron",zh:"\u5361\u4F26\u5BB6\u65CF"},region:"stormlands",seat:"nightsong",tier:"minor",liege:"baratheon",sigil:{en:"Three black nightingales on gold",zh:"\u91D1\u5E95\u4E0A\u4E09\u53EA\u9ED1\u8272\u591C\u83BA"},colors:["#e2b33c","#141414"],summary:{en:"Marcher lords of Nightsong, guarding the western stormlands against Dorne. Lord Bryce Caron was one of Renly's Rainbow Guard; his bastard half-brother Rolland Storm, the Bastard of Nightsong, also appears in the war.",zh:"\u591C\u6B4C\u57CE\u7684\u8FB9\u7586\u8BF8\u4FAF\uFF0C\u9547\u5B88\u98CE\u66B4\u5730\u897F\u90E8\u4EE5\u9632\u591A\u6069\u3002\u5E03\u83B1\u65AF\xB7\u5361\u4F26\u4F2F\u7235\u662F\u84DD\u793C\u7684\u5F69\u8679\u62A4\u536B\u4E4B\u4E00\uFF1B\u4ED6\u7684\u79C1\u751F\u5144\u5F1F\u3001\u201C\u591C\u6B4C\u57CE\u7684\u79C1\u751F\u5B50\u201D\u7F57\u5170\xB7\u98CE\u66B4\u4E5F\u5728\u6218\u4E89\u4E2D\u73B0\u8EAB\u3002"},refs:["acok","twoiaf"],members:[e("bryce-caron","Bryce Caron","\u5E03\u83B1\u65AF\xB7\u5361\u4F26",{note:{en:"Lord of Nightsong, the orange knight of Renly's Rainbow Guard.",zh:"\u591C\u6B4C\u57CE\u4F2F\u7235\uFF0C\u84DD\u793C\u5F69\u8679\u62A4\u536B\u4E2D\u7684\u6A59\u8863\u9A91\u58EB\u3002"},fate:{en:"Refuses to join Stannis after Renly's death and is killed by Ser Philip Foote (A Clash of Kings).",zh:"\u84DD\u793C\u6B7B\u540E\u62D2\u7EDD\u6295\u9760\u53F2\u5766\u5C3C\u65AF\uFF0C\u88AB\u83F2\u5229\u666E\xB7\u4F5B\u7279\u7235\u58EB\u6240\u6740\uFF08\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\uFF09\u3002"}})]},{id:"selmy",names:{en:"House Selmy",zh:"\u8D5B\u5C14\u5F25\u5BB6\u65CF"},region:"stormlands",seat:"harvest-hall",tier:"minor",liege:"baratheon",sigil:{en:"Three stalks of wheat, gold, on brown",zh:"\u68D5\u5E95\u4E0A\u4E09\u652F\u91D1\u8272\u9EA6\u7A57"},colors:["#6b4a2b","#e2b33c"],summary:{en:"A knightly house of Harvest Hall in the Dornish Marches, famous above all for Ser Barristan the Bold, the most celebrated knight of his age and Lord Commander of the Kingsguard.",zh:"\u591A\u6069\u8FB9\u7586\u5730\u4E30\u6536\u5385\u7684\u9A91\u58EB\u5BB6\u65CF\uFF0C\u6700\u51FA\u540D\u7684\u662F\u201C\u65E0\u754F\u7684\u201D\u5DF4\u5229\u65AF\u5766\u7235\u58EB\u2014\u2014\u4ED6\u662F\u90A3\u4E2A\u65F6\u4EE3\u6700\u8D1F\u76DB\u540D\u7684\u9A91\u58EB\uFF0C\u4E5F\u662F\u5FA1\u6797\u94C1\u536B\u961F\u957F\u3002"},refs:["agot","asos","twoiaf"],members:[e("barristan-selmy","Barristan Selmy","\u5DF4\u5229\u65AF\u5766\xB7\u8D5B\u5C14\u5F25",{note:{en:"Barristan the Bold, Lord Commander of the Kingsguard under Robert.",zh:"\u201C\u65E0\u754F\u7684\u201D\u5DF4\u5229\u65AF\u5766\uFF0C\u52B3\u52C3\u5728\u4F4D\u65F6\u7684\u5FA1\u6797\u94C1\u536B\u961F\u957F\u3002"},fate:{en:`Dismissed by Joffrey, he crosses the sea in disguise as "Arstan Whitebeard" and enters Daenerys Targaryen's service (A Clash of Kings / A Storm of Swords).`,zh:"\u88AB\u4E54\u4F5B\u91CC\u89E3\u804C\u540E\uFF0C\u5316\u540D\u201C\u767D\u80E1\u5B50\u963F\u65AF\u5766\u201D\u6E21\u6D77\u6295\u5954\u4E39\u59AE\u8389\u4E1D\xB7\u5766\u683C\u5229\u5B89\uFF08\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\uFF09\u3002"}})]},{id:"swann",names:{en:"House Swann",zh:"\u53F2\u6587\u5BB6\u65CF"},region:"stormlands",seat:"stonehelm",tier:"major",liege:"baratheon",sigil:{en:"Two swans, one black and one white, fighting, on a field divided black and white",zh:"\u9ED1\u767D\u5BF9\u5206\u7684\u5E95\u4E0A\uFF0C\u4E00\u9ED1\u4E00\u767D\u4E24\u53EA\u5929\u9E45\u76F8\u6597"},colors:["#141414","#f2efe6"],summary:{en:"Lords of Stonehelm at the northern end of the Boneway, one of the strongest houses of the Marches. Lord Gulian Swann's sons served on different sides in the war: Ser Balon in the Kingsguard, Ser Donnel with Renly and then Stannis.",zh:"\u9AB8\u9AA8\u8DEF\u5317\u7AEF\u77F3\u76D4\u57CE\u7684\u9886\u4E3B\uFF0C\u662F\u8FB9\u7586\u5730\u4E0A\u6700\u5F3A\u5927\u7684\u5BB6\u65CF\u4E4B\u4E00\u3002\u53E4\u5229\u5B89\xB7\u53F2\u6587\u4F2F\u7235\u7684\u4E24\u4E2A\u513F\u5B50\u5728\u6218\u4E89\u4E2D\u5404\u4E3A\u5176\u4E3B\uFF1A\u62DC\u4F26\u7235\u58EB\u8EAB\u5728\u5FA1\u6797\u94C1\u536B\uFF0C\u5510\u7EB3\u5C14\u7235\u58EB\u5219\u5148\u8FFD\u968F\u84DD\u793C\uFF0C\u540E\u5F52\u53F2\u5766\u5C3C\u65AF\u3002"},refs:["acok","asos","affc","twoiaf"],members:[e("gulian-swann","Gulian Swann","\u53E4\u5229\u5B89\xB7\u53F2\u6587",{note:{en:"Lord of Stonehelm.",zh:"\u77F3\u76D4\u57CE\u4F2F\u7235\u3002"}}),e("balon-swann","Balon Swann","\u62DC\u4F26\xB7\u53F2\u6587",{father:"gulian-swann",note:{en:"Knight of the Kingsguard under Joffrey and Tommen.",zh:"\u4E54\u4F5B\u91CC\u4E0E\u6258\u66FC\u5728\u4F4D\u65F6\u7684\u5FA1\u6797\u94C1\u536B\u3002"}}),e("donnel-swann","Donnel Swann","\u5510\u7EB3\u5C14\xB7\u53F2\u6587",{father:"gulian-swann",note:{en:"Lord Gulian's heir; fought for Renly and later Stannis.",zh:"\u53E4\u5229\u5B89\u4F2F\u7235\u7684\u7EE7\u627F\u4EBA\uFF1B\u5148\u4E3A\u84DD\u793C\u3001\u540E\u4E3A\u53F2\u5766\u5C3C\u65AF\u4F5C\u6218\u3002"}})]},{id:"penrose",names:{en:"House Penrose",zh:"\u76D8\u7F57\u65AF\u5BB6\u65CF"},region:"stormlands",seat:"parchments",tier:"minor",liege:"baratheon",sigil:{en:"Crossed quills, white on russet",zh:"\u8D64\u8910\u5E95\u4E0A\u4EA4\u53C9\u7684\u767D\u8272\u7FBD\u6BDB\u7B14"},colors:["#8a4b2a","#f2efe6"],summary:{en:"A stormland house of Parchments, remembered in the novels for Ser Cortnay Penrose, the stubborn castellan of Storm's End who refused to yield it to Stannis in 299 AC.",zh:"\u7F8A\u76AE\u7EB8\u57CE\u7684\u98CE\u66B4\u5730\u5BB6\u65CF\u3002\u5C0F\u8BF4\u4E2D\u6700\u4EE4\u4EBA\u8BB0\u4F4F\u7684\u662F\u79D1\u5854\u5948\xB7\u76D8\u7F57\u65AF\u7235\u58EB\u2014\u2014299\u5E74\u575A\u51B3\u62D2\u7EDD\u5411\u53F2\u5766\u5C3C\u65AF\u4EA4\u51FA\u98CE\u606F\u5821\u7684\u56FA\u6267\u4EE3\u7406\u57CE\u4E3B\u3002"},refs:["acok","twoiaf"],members:[e("cortnay-penrose","Cortnay Penrose","\u79D1\u5854\u5948\xB7\u76D8\u7F57\u65AF",{note:{en:"Castellan of Storm's End for Renly; guardian of the boy Edric Storm.",zh:"\u4E3A\u84DD\u793C\u9547\u5B88\u98CE\u606F\u5821\u7684\u4EE3\u7406\u57CE\u4E3B\uFF1B\u5C11\u5E74\u827E\u5FB7\u745E\u514B\xB7\u98CE\u66B4\u7684\u76D1\u62A4\u4EBA\u3002"},fate:{en:"Falls to his death from a tower of Storm's End, apparently by dark arts, and the castle yields to Stannis (A Clash of Kings).",zh:"\u4F3C\u4E4E\u56E0\u9ED1\u6697\u6CD5\u672F\u800C\u4ECE\u98CE\u606F\u5821\u5854\u697C\u5760\u4EA1\uFF0C\u57CE\u5821\u968F\u5373\u964D\u4E8E\u53F2\u5766\u5C3C\u65AF\uFF08\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\uFF09\u3002"}})]},{id:"buckler",names:{en:"House Buckler",zh:"\u5DF4\u514B\u52D2\u5BB6\u65CF"},region:"stormlands",seat:"bronzegate",tier:"minor",liege:"baratheon",sigil:n,colors:["#3a5a8c","#b07a3a"],summary:{en:"Lords of Bronzegate on the kingsroad between King's Landing and Storm's End, long sworn to the Baratheons. Lord Ralph Buckler is among the stormlords in the War of the Five Kings.",zh:"\u94DC\u95E8\u57CE\u7684\u9886\u4E3B\uFF0C\u57CE\u5821\u4F4D\u4E8E\u541B\u4E34\u4E0E\u98CE\u606F\u5821\u4E4B\u95F4\u7684\u56FD\u738B\u5927\u9053\u4E0A\uFF0C\u4E16\u4EE3\u6548\u5FE0\u62DC\u62C9\u5E2D\u6069\u5BB6\u65CF\u3002\u62C9\u5C14\u592B\xB7\u5DF4\u514B\u52D2\u4F2F\u7235\u662F\u4E94\u738B\u4E4B\u6218\u4E2D\u7684\u98CE\u66B4\u5730\u8BF8\u4FAF\u4E4B\u4E00\u3002"},refs:["acok","twoiaf"]},{id:"fell",names:{en:"House Fell",zh:"\u8D39\u5C14\u5BB6\u65CF"},region:"stormlands",seat:"felwood",tier:"minor",liege:"baratheon",sigil:n,colors:["#2f5a3a","#d8d2c0"],summary:{en:"Lords of Felwood in the northern stormlands. Lord Fell stayed loyal to King Aerys in 282 AC and fell to Robert Baratheon at Summerhall.",zh:"\u98CE\u66B4\u5730\u5317\u90E8\u8D39\u5C14\u6797\u5821\u7684\u9886\u4E3B\u3002282\u5E74\uFF0C\u8D39\u5C14\u4F2F\u7235\u6548\u5FE0\u4F0A\u91CC\u65AF\u56FD\u738B\uFF0C\u5728\u76DB\u590F\u5385\u8D25\u4E8E\u52B3\u52C3\xB7\u62DC\u62C9\u5E2D\u6069\u4E4B\u624B\u3002"},refs:["twoiaf"]},{id:"grandison",names:{en:"House Grandison",zh:"\u845B\u5170\u72C4\u68EE\u5BB6\u65CF"},region:"stormlands",seat:"grandview",tier:"minor",liege:"baratheon",sigil:{en:"A sleeping black lion on yellow",zh:"\u9EC4\u5E95\u4E0A\u4E00\u5934\u6C89\u7761\u7684\u9ED1\u72EE"},colors:["#e0c04a","#141414"],summary:{en:"Lords of Grandview. Lord Grandison was one of the loyalists who mustered at Summerhall against Robert in 282 AC and was defeated there.",zh:"\u8FDC\u666F\u5821\u7684\u9886\u4E3B\u3002282\u5E74\uFF0C\u845B\u5170\u72C4\u68EE\u4F2F\u7235\u662F\u5728\u76DB\u590F\u5385\u96C6\u7ED3\u8BA8\u4F10\u52B3\u52C3\u7684\u6548\u5FE0\u6D3E\u4E4B\u4E00\uFF0C\u5E76\u5728\u90A3\u91CC\u6218\u8D25\u3002"},refs:["twoiaf"]},{id:"cafferen",names:{en:"House Cafferen",zh:"\u5361\u592B\u4F26\u5BB6\u65CF"},region:"stormlands",seat:"fawnton",tier:"minor",liege:"baratheon",sigil:n,colors:["#c47a2c","#f2efe6"],summary:{en:"Lords of Fawnton in the stormlands, among the houses that held to the Targaryens when Robert rose and were beaten by him at Summerhall.",zh:"\u98CE\u66B4\u5730\u5C0F\u9E7F\u57CE\u7684\u9886\u4E3B\u3002\u52B3\u52C3\u8D77\u5175\u65F6\uFF0C\u4ED6\u4EEC\u7AD9\u5728\u5766\u683C\u5229\u5B89\u4E00\u65B9\uFF0C\u7ED3\u679C\u5728\u76DB\u590F\u5385\u88AB\u52B3\u52C3\u51FB\u8D25\u3002"},refs:["twoiaf"]},{id:"errol",names:{en:"House Errol",zh:"\u827E\u7F57\u5C14\u5BB6\u65CF"},region:"stormlands",seat:"haystack-hall",tier:"minor",liege:"baratheon",sigil:n,colors:["#c98a2c","#e8d27a"],summary:{en:"Lords of Haystack Hall near Shipbreaker Bay, a minor house sworn to Storm's End.",zh:"\u7834\u8239\u6E7E\u9644\u8FD1\u8349\u579B\u5385\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u98CE\u606F\u5821\u7684\u5C0F\u5BB6\u65CF\u3002"},refs:["acok","twoiaf"]},{id:"trant",names:{en:"House Trant",zh:"\u7279\u6069\u7279\u5BB6\u65CF"},region:"stormlands",seat:"gallowsgrey",tier:"minor",liege:"baratheon",sigil:n,colors:["#6a6a6a","#2f6a3a"],summary:{en:"A minor house of Gallowsgrey, sworn to Storm's End and best known for Ser Meryn Trant of the Kingsguard, a cruel instrument of King Joffrey.",zh:"\u7070\u7EDE\u67B6\u5821\u7684\u5C0F\u5BB6\u65CF\uFF0C\u6548\u5FE0\u98CE\u606F\u5821\uFF0C\u6700\u51FA\u540D\u7684\u662F\u5FA1\u6797\u94C1\u536B\u9A6C\u6797\xB7\u7279\u6069\u7279\u7235\u58EB\u2014\u2014\u4E54\u4F5B\u91CC\u56FD\u738B\u624B\u4E0B\u7684\u6B8B\u5FCD\u722A\u7259\u3002"},refs:["agot","acok","twoiaf"],members:[e("meryn-trant","Meryn Trant","\u9A6C\u6797\xB7\u7279\u6069\u7279",{note:{en:"Knight of the Kingsguard under Robert, Joffrey and Tommen.",zh:"\u52B3\u52C3\u3001\u4E54\u4F5B\u91CC\u4E0E\u6258\u66FC\u4E09\u671D\u7684\u5FA1\u6797\u94C1\u536B\u3002"}})]},{id:"wylde",names:{en:"House Wylde",zh:"\u5A01\u5C14\u5FB7\u5BB6\u65CF"},region:"stormlands",seat:"rain-house",tier:"minor",liege:"baratheon",sigil:n,colors:["#3a5a7a","#c8d2dc"],summary:{en:"Lords of Rain House on Cape Wrath, sworn to Storm's End. Lord Casper Wylde is among the stormlords of the War of the Five Kings.",zh:"\u6012\u89D2\u96E8\u5C4B\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u98CE\u606F\u5821\u3002\u5361\u65AF\u73C0\xB7\u5A01\u5C14\u5FB7\u4F2F\u7235\u662F\u4E94\u738B\u4E4B\u6218\u4E2D\u7684\u98CE\u66B4\u5730\u8BF8\u4FAF\u4E4B\u4E00\u3002"},refs:["acok","twoiaf"]},{id:"morrigen",names:{en:"House Morrigen",zh:"\u83AB\u91CC\u6839\u5BB6\u65CF"},region:"stormlands",seat:"crows-nest",tier:"minor",liege:"baratheon",sigil:{en:"A black crow in flight on storm-green",zh:"\u98CE\u66B4\u7EFF\u5E95\u4E0A\u4E00\u53EA\u98DE\u7FD4\u7684\u9ED1\u9E26"},colors:["#4c6b58","#141414"],summary:{en:`Lords of Crow's Nest on Cape Wrath. Ser Guyard Morrigen, "Guyard the Green", was one of the knights of Renly's Rainbow Guard.`,zh:"\u6012\u89D2\u9E26\u5DE2\u5821\u7684\u9886\u4E3B\u3002\u201C\u7EFF\u8863\u201D\u76D6\u4E9A\u5FB7\xB7\u83AB\u91CC\u6839\u7235\u58EB\u662F\u84DD\u793C\u5F69\u8679\u62A4\u536B\u4E2D\u7684\u4E00\u5458\u3002"},refs:["acok","twoiaf"],members:[e("guyard-morrigen","Guyard Morrigen","\u76D6\u4E9A\u5FB7\xB7\u83AB\u91CC\u6839",{note:{en:"The green knight of Renly's Rainbow Guard; later fights for Stannis.",zh:"\u84DD\u793C\u5F69\u8679\u62A4\u536B\u4E2D\u7684\u7EFF\u8863\u9A91\u58EB\uFF1B\u540E\u6765\u4E3A\u53F2\u5766\u5C3C\u65AF\u4F5C\u6218\u3002"},fate:{en:"Killed in the Battle of the Blackwater (A Clash of Kings).",zh:"\u6218\u6B7B\u4E8E\u9ED1\u6C34\u6CB3\u4E4B\u5F79\uFF08\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\uFF09\u3002"}})]},{id:"mertyns",names:{en:"House Mertyns",zh:"\u6885\u5C14\u5EF7\u65AF\u5BB6\u65CF"},region:"stormlands",seat:"mistwood",tier:"minor",liege:"baratheon",sigil:n,colors:["#3d5a4a","#cfd6cf"],summary:{en:"Lords of Mistwood in the Rainwood on Cape Wrath, a minor house sworn to Storm's End.",zh:"\u6012\u89D2\u96E8\u6797\u4E2D\u96FE\u6797\u5821\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u98CE\u606F\u5821\u7684\u5C0F\u5BB6\u65CF\u3002"},refs:["adwd","twoiaf"]},{id:"peasebury",names:{en:"House Peasebury",zh:"\u76AE\u65AF\u4F2F\u91CC\u5BB6\u65CF"},region:"stormlands",seat:"poddingfield",tier:"minor",liege:"baratheon",sigil:n,colors:["#5a7a3a","#e6e0c8"],summary:{en:"Lords of Poddingfield, a minor house of the stormlands sworn to Storm's End.",zh:"\u8C46\u7530\u5821\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u98CE\u606F\u5821\u7684\u98CE\u66B4\u5730\u5C0F\u5BB6\u65CF\u3002"},refs:["acok","twoiaf"]},{id:"rogers",names:{en:"House Rogers",zh:"\u7F57\u6770\u65AF\u5BB6\u65CF"},region:"stormlands",seat:"amberly",tier:"minor",liege:"baratheon",sigil:n,colors:["#7a6a4a","#e6d8b0"],summary:{en:"A minor stormland house of Amberly, sworn to Storm's End; it is named in the companion histories with little detail.",zh:"\u5B89\u67CF\u5229\u7684\u98CE\u66B4\u5730\u5C0F\u5BB6\u65CF\uFF0C\u6548\u5FE0\u98CE\u606F\u5821\uFF1B\u5B98\u65B9\u7F16\u5E74\u53F2\u4E2D\u4EC5\u63D0\u5176\u540D\uFF0C\u7EC6\u8282\u5BE5\u5BE5\u3002"},refs:["twoiaf"]},{id:"staedmon",names:{en:"House Staedmon",zh:"\u53F2\u6234\u8499\u5BB6\u65CF"},region:"stormlands",seat:"broad-arch",tier:"minor",liege:"baratheon",sigil:n,colors:["#6a5a4a","#d8c8a0"],summary:{en:"Lords of Broad Arch in the stormlands, sworn to Storm's End. The histories remember a Lord Staedmon called Pennylover for his tight purse.",zh:"\u98CE\u66B4\u5730\u5BBD\u62F1\u5821\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u98CE\u606F\u5821\u3002\u53F2\u4E66\u8BB0\u8F7D\u6709\u4E00\u4F4D\u56E0\u541D\u556C\u800C\u88AB\u79F0\u4F5C\u201C\u7231\u8D22\u8005\u201D\u7684\u53F2\u6234\u8499\u4F2F\u7235\u3002"},refs:["twoiaf"]},{id:"toyne",names:{en:"House Toyne",zh:"\u6258\u56E0\u5BB6\u65CF"},region:"stormlands",seat:null,tier:"extinct",liege:"baratheon",sigil:n,colors:["#5a5a5a","#a8a8a8"],summary:{en:"An extinct house of the stormlands. Ser Terrence Toyne of the Kingsguard was executed for taking King Aegon IV's mistress as his lover, and the house was ruined in the aftermath.",zh:"\u98CE\u66B4\u5730\u4E00\u4E2A\u5DF2\u7ECF\u65AD\u7EDD\u7684\u5BB6\u65CF\u3002\u5FA1\u6797\u94C1\u536B\u6CF0\u4F26\u65AF\xB7\u6258\u56E0\u7235\u58EB\u56E0\u4E0E\u4F0A\u803F\u56DB\u4E16\u56FD\u738B\u7684\u60C5\u5987\u79C1\u901A\u800C\u88AB\u5904\u6B7B\uFF0C\u5BB6\u65CF\u968F\u4E4B\u8D25\u843D\u3002"},refs:["twoiaf"],members:[e("terrence-toyne","Terrence Toyne","\u6CF0\u4F26\u65AF\xB7\u6258\u56E0",{note:{en:"Knight of the Kingsguard under Aegon IV; executed for his affair with the king's mistress.",zh:"\u4F0A\u803F\u56DB\u4E16\u65F6\u671F\u7684\u5FA1\u6797\u94C1\u536B\uFF1B\u56E0\u4E0E\u56FD\u738B\u60C5\u5987\u79C1\u901A\u800C\u88AB\u5904\u6B7B\u3002"}})]}]};export{s as default};
